# Look for long reverse-complement matches (inverted repeats): substring at i equals rc of substring at j
# Approach: for k in sizes, find k-mers that equal rc of another k-mer (non-overlapping-ish)
from collections import defaultdict
for k in [8, 10, 12, 15, 20]:
    pos = defaultdict(list)
    for i in range(n-k+1):
        pos[seq[i:i+k]].append(i)
    found=[]
    seen=set()
    for kk, lst in pos.items():
        rkk = rc(kk)
        if rkk in pos and rkk != kk:
            for a in lst:
                for b in pos[rkk]:
                    if a < b and (b-a) >= k:
                        found.append((a,b))
    # dedupe
    found = sorted(set(found))
    if found:
        print(f"k={k}: {len(found)} inverted repeat pairs, first few:")
        for a,b in found[:15]:
            print(f"   {a+1}({seq[a:a+k]}) .. {b+1}({seq[b:b+k]})")
    else:
        print(f"k={k}: none")
    print()

