# search palindromic stems (hairpins): left arm [i,i+L), right arm [j,j+L) with rc(left)=right, loop=j-(i+L)
best=[]
Lmin=12
for i in range(n-2*Lmin-3):
    for j in range(i+Lmin+3, min(i+Lmin+60, n-Lmin)):
        # compare seq[i:i+L] with rc(seq[j:j+L]) increasing L
        L=0
        mm=0
        while i+L<n and j+L<n:
            if seq[i+L]==comp[seq[j+L]]:
                pass
            else:
                mm+=1
                if mm>1: break
            L+=1
        if L>=Lmin and mm<=1:
            best.append((L,mm,i,j))
best.sort(reverse=True)
print("top approximate hairpins (stem L, mismatches, i1, j1, loop):")
for L,mm,i,j in best[:10]:
    print(f"  stem {L} mm {mm} left {i+1}-{i+L}, right {j+1}-{j+L}, loop {j-(i+L)}")
